import { spawn } from 'node:child_process';
const bot = process.env.BOT;
const t = Date.UTC(2026, 9, 23, 12, 0, 0);
const childCode = (idx) => `
import { reserve } from ${JSON.stringify(bot)};
const now = new Date(${t});
const out = [];
for (const ch of ['sms','push']) out.push(['u1', await reserve('u1', ch, now)]);
if (${idx} < 4) out.push(['u2', await reserve('u2', 'chat', now)]);
console.log(JSON.stringify(out));
`;
const runChild = (idx) => new Promise((resolve, reject) => {
  const p = spawn(process.execPath, ['--input-type=module', '-e', childCode(idx)], { env: process.env });
  let out = '', err = '';
  p.stdout.on('data', d => out += d); p.stderr.on('data', d => err += d);
  p.on('close', code => code === 0 ? resolve(JSON.parse(out)) : reject(new Error(err)));
});
const results = (await Promise.all([...Array(8).keys()].map(runChild))).flat();
const u1 = results.filter(([u]) => u === 'u1').map(([, r]) => r);
const u2 = results.filter(([u]) => u === 'u2').map(([, r]) => r);
const u1Allowed = u1.filter(r => r.allowed).length;
const u1RetryOk = u1.filter(r => !r.allowed).every(r => r.retryAt === new Date(t + 86400000).toISOString());
console.log('u1 calls', u1.length, 'allowed', u1Allowed, 'denied', u1.length - u1Allowed, 'retryAt all t+24h:', u1RetryOk);
console.log('u2 calls', u2.length, 'allowed', u2.filter(r => r.allowed).length, '(expect 4 of 4)');

// Window boundary, same process, different customer u4
const { reserve } = await import(bot);
const a = [];
for (let i = 0; i < 5; i++) a.push(await reserve('u4', ['sms','push','chat'][i % 3], new Date(t)));
const sixth = await reserve('u4', 'sms', new Date(t));
console.log('u4 first 5 allowed:', a.every(r => r.allowed), '| 6th allowed:', sixth.allowed, '| 6th retryAt:', sixth.retryAt?.toISOString());
const justBefore = await reserve('u4', 'push', new Date(t + 86400000 - 1));
const atRetry = await reserve('u4', 'push', new Date(t + 86400000));
console.log('at t+24h-1ms allowed:', justBefore.allowed, '| at t+24h allowed:', atRetry.allowed);
console.log('sample denial reason:', sixth.reason);
EOF
